package utp.siga.catalog.interfaces.rest;
import java.util.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*; import utp.siga.catalog.application.port.out.SupplierStore; import utp.siga.catalog.application.usecase.SupplierService; import utp.siga.catalog.domain.model.Supplier;
@RestController @Validated @RequestMapping("/api/v1/suppliers") public class SupplierController { final SupplierService s; public SupplierController(SupplierService s){this.s=s;} public record Request(@NotNull String code,@NotNull String taxId,@NotNull String businessName,String tradeName,String contactName,String phone,String email,String address,Boolean active,Long expectedVersion){} public record Response(UUID id,String code,String taxId,String businessName,String tradeName,String contactName,String phone,String email,String address,boolean active,long version){} public record Page(List<Response> content,int page,int size,long totalElements){}
 @PostMapping public ResponseEntity<Response> create(@RequestBody Request r,HttpServletRequest h){Supplier x=value(null,r,r.active()==null||r.active(),0);return ResponseEntity.status(201).body(response(s.create(x,UUID.fromString((String)h.getAttribute("correlationId")))));}
 @GetMapping public Page list(@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(100)int size,@RequestParam(defaultValue="code,asc")String sort,@RequestParam(required=false)String q,@RequestParam(required=false)Boolean active){var v=s.page(page,size,sort,q,active);return new Page(v.content().stream().map(this::response).toList(),page,size,v.total());}
 @GetMapping("/{id}") public Response get(@PathVariable UUID id){return response(s.get(id));}
 @PutMapping("/{id}") public Response put(@PathVariable UUID id,@RequestBody Request r,HttpServletRequest h){if(r.active()==null||r.expectedVersion()==null)throw new IllegalArgumentException();return response(s.update(value(id,r,r.active(),r.expectedVersion()),r.expectedVersion(),UUID.fromString((String)h.getAttribute("correlationId"))).supplier());}
 private Supplier value(UUID id,Request r,boolean active,long v){return new Supplier(id,r.code(),r.taxId(),r.businessName(),r.tradeName(),r.contactName(),r.phone(),r.email(),r.address(),active,v);} private Response response(Supplier x){return new Response(x.id(),x.code(),x.taxId(),x.businessName(),x.tradeName(),x.contactName(),x.phone(),x.email(),x.address(),x.active(),x.version());}
}
